-- Календарь рыночных событий MOEX/ЦБ РФ и пользовательские алерты по цене/RSI (backend#95).
-- Пороговые значения хранятся как NUMERIC (INV-6).

CREATE TABLE marketdata.market_event (
    id          BIGSERIAL    PRIMARY KEY,
    event_date  DATE         NOT NULL,
    event_type  VARCHAR(16)  NOT NULL CHECK (event_type IN ('CBR_RATE', 'EARNINGS', 'DIVIDEND', 'MACRO')),
    ticker      VARCHAR(32)  NULL,
    title       VARCHAR(180) NOT NULL,
    importance  VARCHAR(16)  NOT NULL CHECK (importance IN ('HIGH', 'MEDIUM', 'LOW')),
    description TEXT         NOT NULL
);

CREATE INDEX idx_market_event_date
    ON marketdata.market_event (event_date ASC, id ASC);

CREATE INDEX idx_market_event_type_date
    ON marketdata.market_event (event_type, event_date ASC, id ASC);

CREATE INDEX idx_market_event_upper_ticker_date
    ON marketdata.market_event (UPPER(ticker), event_date ASC, id ASC);

