CREATE TABLE sessions.price_alert (
    id              UUID           PRIMARY KEY,
    user_id         UUID           NOT NULL,
    ticker          VARCHAR(32)    NOT NULL,
    condition_type  VARCHAR(24)    NOT NULL CHECK (condition_type IN ('PRICE_ABOVE', 'PRICE_BELOW', 'RSI_BELOW', 'RSI_ABOVE')),
    threshold_value NUMERIC(18, 4) NOT NULL CHECK (threshold_value > 0),
    active          BOOLEAN        NOT NULL DEFAULT TRUE,
    note            VARCHAR(200)   NULL,
    created_at      TIMESTAMPTZ    NOT NULL DEFAULT now()
);

CREATE INDEX idx_price_alert_user_created
    ON sessions.price_alert (user_id, created_at DESC, id DESC);

CREATE INDEX idx_price_alert_user_active
    ON sessions.price_alert (user_id, active);
